import numpy as np
from treehfd import XGBTreeHFD


def _residual_mse(model, X, eta0, comps):
    pred = model.predict(X)
    approx = np.full(X.shape[0], eta0, dtype=float)
    for idx, vals in comps.items():
        approx = approx + vals
    return float(np.mean((approx - pred) ** 2))


def _fit_predict(model, X_tr, X_va, depth_variable):
    hfd = XGBTreeHFD(model)
    hfd.fit(X_tr, interaction_order=2, depth_variable=depth_variable, verbose=False)
    y_main, y_order2 = hfd.predict(X_va, verbose=False)
    comps = {(j,): y_main[:, j] for j in range(y_main.shape[1])}
    for k, (a, b) in enumerate(hfd.interaction_list):
        comps[(int(a), int(b))] = y_order2[:, k]
    return float(hfd.eta0), comps


def decompose(model, X_train, X_test):
    n = X_train.shape[0]
    rng = np.random.RandomState(0)
    perm = rng.permutation(n)
    n_val = max(1, int(0.25 * n))
    va_idx, tr_idx = perm[:n_val], perm[n_val:]
    X_tr, X_va = X_train[tr_idx], X_train[va_idx]

    candidates = [1, 2, 3]
    best = None
    best_mse = np.inf
    for dv in candidates:
        try:
            eta0, comps = _fit_predict(model, X_tr, X_va, dv)
        except Exception:
            continue
        mse = _residual_mse(model, X_va, eta0, comps)
        if mse < best_mse:
            best_mse = mse
            best = dv

    if best is None:
        best = 2

    hfd = XGBTreeHFD(model)
    hfd.fit(X_train, interaction_order=2, depth_variable=best, verbose=False)
    y_main, y_order2 = hfd.predict(X_test, verbose=False)
    comps = {(j,): y_main[:, j] for j in range(y_main.shape[1])}
    for k, (a, b) in enumerate(hfd.interaction_list):
        comps[(int(a), int(b))] = y_order2[:, k]
    return float(hfd.eta0), comps
